callGraph.callee:
sessions
        .iter()
        .filter_map(|(session_id, session)| {
            session.pid.map(|pid| {
                (
                    session_id.clone(),
                    pid,
                    session.shell.clone(),
                    session.unacked_bytes.load(Ordering::Relaxed),
                )
            })
        }).collect

pids_to_query
        .iter()
        .map(|(session_id, pid, shell, buffer_bytes)| {
            let memory_mb = sys
                .process(Pid::from_u32(*pid))
                .map(|p| p.memory() as f64 / 1024.0 / 1024.0)
                .unwrap_or(0.0);

            PtyMemoryInfo {
                session_id: session_id.clone(),
                pid: Some(*pid),
                shell: shell.clone(),
                memory_mb,
                buffer_bytes: *buffer_bytes,
                scrollback_lines: 0,
            }
        }).collect

INTEGRATION_DIR
        .get_or_init(|| match setup_integration_dir() {
            Ok(dir) => Some(dir),
            Err(err) => {
                warn!("Shell integration setup failed: {err}");
                None
            }
        }).as_deref

pattern
            .replace_all(&redacted, |captures: &regex::Captures<'_>| {
                if captures.len() > 1 {
                    format!("{}{}", &captures[1], REDACTION_PLACEHOLDER)
                } else {
                    REDACTION_PLACEHOLDER.to_string()
                }
            }).into_owned
